    d=json.load(open(f)); c=d['case']; o=d['outcome']; b=c['buyer']
    if b['category_goal'] not in('stabilise','secure_supply'): continue
    cases[c['case_id']]=(c,o,d)
    if o.get('deal'): deals.setdefault(c['case_id'],[]).append((o['terms'],o['cost_breakdown']['relationship'],o['c_deal'],f.split('/')[-1][:6]))
def fitcase(cid, std_pay, rates, fcs):
    c,o,d=cases[cid]
    best=None
    for r in rates:
        for fc in fcs:
            sup={'standard':{'payment_days':std_pay,'incoterm':c['fixed_terms'].get('incoterm','DAP'),'ppm_commitment':0,'chargeback_eur_per_complaint':0,'tooling_eur':0},'interest_rate':r,'full_cost':fc}
            err=0
            for t,rel,cd,_ in deals[cid]:
                bd=cost_breakdown(c,t,supplier=sup)
                err+=(bd['relationship']-rel)**2
            if best is None or err<best[0]: best=(err,r,fc,sup)
    return best
import sys
cfg={'case:P02':(30,np.arange(0.0,0.201,0.005),np.arange(355,380,0.01)),
     'case:P01':(30,np.arange(0.0,0.401,0.005),np.arange(120,140,0.01)),
     'case:P03':(30,np.arange(0.0,0.201,0.005),np.arange(380,410,0.02)),}
for cid,(sp,rates,fcs) in cfg.items():
    c,o,d=cases[cid]
    err,r,fc,sup=fitcase(cid,sp,rates,fcs)
    print('\n==',cid,'fit rate',round(r,3),'full_cost',round(fc,2),'rmse',round(math.sqrt(err/len(deals[cid])),1),'n',len(deals[cid]))
    for t,rel,cd,sid in deals[cid]:
        print('   ',sid,'recorded rel',rel,'model rel',round(cost_breakdown(c,t,supplier=sup)['relationship'],1),'c_deal',cd,'model C',total_cost(c,t,supplier=sup))
    fields=[f for f in c['negotiable'] if f!='unit_price']
    opts=[c['term_options'].get(f,[None]) for f in fields]
    res=[]
