        std={'ppm_commitment':o['terms'].get('ppm_commitment'),'chargeback_eur_per_complaint':o['terms'].get('chargeback_eur_per_complaint')} if o.get('terms') else {}
        bestp=min(((total_cost(c,{**t,'unit_price':p},standard=std,supplier=sup),p) for p in np.arange(fc*0.85,fc*1.1,0.01)))
        res.append((bestp[0],round(bestp[1],2),t))
    res.sort(key=lambda x:x[0])
    print('  c_open',o['c_open'],'c_best',o['c_best'])
    for C,p,t in res[:8]:
        tt={k:(('db%s'%v['deadband_pct']) if isinstance(v,dict) else v) for k,v in t.items()}
        bd=cost_breakdown(c,{**t,'unit_price':p},standard=std,supplier=sup)
        print(f"   minC={C:,.0f} at p={p} {tt} rel={bd['relationship']:,.0f} score={(o['c_open']-C)/(o['c_open']-o['c_best']):.3f}")
EOF
